function solve(input) {
  const { tree } = input;
  if (!tree || tree.length === 0) return true;
  function validate(idx, min, max) {
    if (idx >= tree.length || tree[idx] === null || tree[idx] === undefined) return true;
    const val = tree[idx];
    if (val <= min || val >= max) return false;
    return validate(2 * idx + 1, min, val) && validate(2 * idx + 2, val, max);
  }
  return validate(0, -Infinity, Infinity);
}
